152→std::tuple<torch::Tensor, std::optional<torch::Tensor>>
153→segment_coo_cuda(torch::Tensor src, torch::Tensor index,
154→                 std::optional<torch::Tensor> optional_out,
155→                 std::optional<int64_t> dim_size, std::string reduce) {
156→  CHECK_CUDA(src);
157→  CHECK_CUDA(index);
158→  if (optional_out.has_value())
159→    CHECK_CUDA(optional_out.value());
160→  c10::cuda::MaybeSetDevice(src.get_device());
161→
162→  CHECK_INPUT(src.dim() >= index.dim());
163→
164→  auto sizes = index.sizes().vec();
165→  for (int i = 0; i < index.dim(); i++) {
166→    sizes[i] = src.size(i);
167→  }
168→  index = index.expand(sizes);
169→
170→  auto dim = index.dim() - 1;
171→
172→  src = src.contiguous();
173→
174→  torch::Tensor out;
175→  if (optional_out.has_value()) {
176→    out = optional_out.value().contiguous();
177→    for (int i = 0; i < out.dim(); i++)
178→      if (i != dim)
179→        CHECK_INPUT(src.size(i) == out.size(i));
180→  } else {
181→    sizes = src.sizes().vec();
182→    if (dim_size.has_value())
183→      sizes[dim] = dim_size.value();
184→    else if (index.numel() == 0)
185→      sizes[dim] = 0;
186→    else {
187→      auto tmp = index.select(dim, index.size(dim) - 1);
188→      tmp = tmp.numel() > 1 ? tmp.max() : tmp;
189→      sizes[dim] = 1 + tmp.cpu().data_ptr<int64_t>()[0];
190→    }
191→    out = torch::zeros(sizes, src.options());
192→  }
193→
194→  std::optional<torch::Tensor> arg_out = std::nullopt;
195→  int64_t *arg_out_data = nullptr;
196→  if (reduce2REDUCE.at(reduce) == MIN || reduce2REDUCE.at(reduce) == MAX) {
197→    arg_out = torch::full_like(out, src.size(dim), index.options());
198→    arg_out_data = arg_out.value().data_ptr<int64_t>();
199→  } else if (reduce2REDUCE.at(reduce) == MEAN) {
200→    auto sizes = index.sizes().vec();
201→    sizes[dim] = out.size(dim);
202→    arg_out = torch::zeros(sizes, out.options());
203→  }
204→
205→  if (index.numel() == 0)
206→    return std::make_tuple(out, arg_out);
207→
208→  auto E = index.numel();
209→  auto E_2 = index.size(dim);
210→  auto E_1 = index.numel() / E_2;
211→  auto K = src.numel() / E;
212→  auto N = out.size(dim);
213→  auto avg_len = (float)E_2 / (float)N;
214→
215→  auto index_info = at::cuda::detail::getTensorInfo<int64_t, int>(index);
216→  auto stream = at::cuda::getCurrentCUDAStream();
217→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
218→    auto src_data = src.data_ptr<scalar_t>();
219→    auto out_data = out.data_ptr<scalar_t>();
220→
221→    AT_DISPATCH_REDUCTION_TYPES(reduce, [&] {
222→      if (!optional_out.has_value())
223→        out.fill_(Reducer<scalar_t, REDUCE>::init());
224→
225→      if (K == 1)
226→        segment_coo_kernel<scalar_t, REDUCE, true>
227→            <<<BLOCKS(1, E), THREADS, 0, stream>>>(src_data, index_info,
228→                                                   out_data, E, N);
229→      else if (avg_len <= 8)
230→        segment_coo_broadcast_kernel<scalar_t, REDUCE, 4>
231→            <<<dim3((E_1 * ((E_2 + 3) / 4) + 7) / 8, (K + 31) / 32),
232→               dim3(32, 8), 0, stream>>>(src_data, index_info, out_data, E, K,
233→                                         N);
234→      else if (avg_len <= 16)
235→        segment_coo_broadcast_kernel<scalar_t, REDUCE, 8>
236→            <<<dim3((E_1 * ((E_2 + 7) / 8) + 7) / 8, (K + 31) / 32),
237→               dim3(32, 8), 0, stream>>>(src_data, index_info, out_data, E, K,
238→                                         N);
239→      else if (avg_len <= 32)
240→        segment_coo_broadcast_kernel<scalar_t, REDUCE, 16>
241→            <<<dim3((E_1 * ((E_2 + 15) / 16) + 7) / 8, (K + 31) / 32),
242→               dim3(32, 8), 0, stream>>>(src_data, index_info, out_data, E, K,
243→                                         N);
244→      else
245→        segment_coo_broadcast_kernel<scalar_t, REDUCE, 32>
246→            <<<dim3((E_1 * ((E_2 + 31) / 32) + 7) / 8, (K + 31) / 32),
247→               dim3(32, 8), 0, stream>>>(src_data, index_info, out_data, E, K,
248→                                         N);
249→
250→      if (!optional_out.has_value() && (REDUCE == MIN || REDUCE == MAX))
251→        out.masked_fill_(out == Reducer<scalar_t, REDUCE>::init(), (scalar_t)0);
252→
253→      if (REDUCE == MIN || REDUCE == MAX) {
254→        if (K == 1)
255→          segment_coo_arg_kernel<scalar_t>
256→              <<<BLOCKS(1, E), THREADS, 0, stream>>>(
257→                  src_data, index_info, out_data, arg_out_data, E, N);
258→        else
259→          segment_coo_arg_broadcast_kernel<scalar_t>
260→              <<<BLOCKS(1, E * K), THREADS, 0, stream>>>(
261→                  src_data, index_info, out_data, arg_out_data, E, K, N);
262→      }
263→
264→      if (REDUCE == MEAN) {
265→        auto count_data = arg_out.value().data_ptr<scalar_t>();
266→        segment_coo_kernel<scalar_t, SUM, false>
267→            <<<BLOCKS(1, E), THREADS, 0, stream>>>(nullptr, index_info,
268→                                                   count_data, E, N);
269→        arg_out.value().masked_fill_(arg_out.value() < (scalar_t)1,
270→                                     (scalar_t)1);
271→        auto count = arg_out.value();
272→        for (int i = dim + 1; i < out.dim(); i++)
273→          count = count.unsqueeze(-1);
274→        if (out.is_floating_point())
275→          out.true_divide_(count);
276→        else
277→          out.div_(count, "floor");
278→      }
279→    });
280→  });
281→
282→  return std::make_tuple(out, arg_out);
283→}
