285→template <typename scalar_t>
286→__global__ void
287→gather_coo_kernel(const scalar_t *src_data,
288→                  const at::cuda::detail::TensorInfo<int64_t, int> index_info,
289→                  scalar_t *out_data, size_t E, size_t N) {
290→
291→  int row_idx = blockIdx.x * blockDim.x + threadIdx.x;
292→
293→  if (row_idx < E) {
294→    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
295→        row_idx, index_info);
296→    int row = index_info.data[offset];
297→
298→    offset = (row_idx / index_info.sizes[index_info.dims - 1]) * N;
299→    scalar_t val = __ldg(src_data + offset + row);
300→
301→    out_data[row_idx] = val;
302→  }
303→}
304→
305→template <typename scalar_t>
306→__global__ void gather_coo_broadcast_kernel(
307→    const scalar_t *src_data,
308→    const at::cuda::detail::TensorInfo<int64_t, int> index_info,
309→    scalar_t *out_data, size_t E, size_t K, size_t N) {
310→
311→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
312→  int row_idx = thread_idx / K;
313→  int col_idx = thread_idx % K;
314→
315→  if (thread_idx < E * K) {
316→    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
317→        row_idx, index_info);
318→    int row = index_info.data[offset];
319→
320→    offset = (row_idx / index_info.sizes[index_info.dims - 1]) * N * K;
321→    scalar_t val = __ldg(src_data + offset + K * row + col_idx);
322→
323→    out_data[thread_idx] = val;
324→  }
325→}
