327→torch::Tensor gather_coo_cuda(torch::Tensor src, torch::Tensor index,
328→                              std::optional<torch::Tensor> optional_out) {
329→  CHECK_CUDA(src);
330→  CHECK_CUDA(index);
331→  if (optional_out.has_value())
332→    CHECK_CUDA(optional_out.value());
333→  c10::cuda::MaybeSetDevice(src.get_device());
334→
335→  CHECK_INPUT(src.dim() >= index.dim());
336→
337→  auto sizes = index.sizes().vec();
338→  for (auto i = 0; i < index.dim() - 1; i++)
339→    sizes[i] = src.size(i);
340→  index = index.expand(sizes);
341→
342→  auto dim = index.dim() - 1;
343→
344→  src = src.contiguous();
345→
346→  torch::Tensor out;
347→  if (optional_out.has_value()) {
348→    out = optional_out.value().contiguous();
349→    for (auto i = 0; i < src.dim(); i++)
350→      if (i != dim)
351→        CHECK_INPUT(src.size(i) == out.size(i));
352→    CHECK_INPUT(index.size(dim) == out.size(dim));
353→  } else {
354→    auto sizes = src.sizes().vec();
355→    sizes[dim] = index.size(dim);
356→    out = torch::empty(sizes, src.options());
357→  }
358→
359→  if (index.numel() == 0)
360→    return out;
361→
362→  auto E = index.numel();
363→  auto K = out.numel() / E;
364→  auto N = src.size(dim);
365→
366→  auto index_info = at::cuda::detail::getTensorInfo<int64_t, int>(index);
367→  auto stream = at::cuda::getCurrentCUDAStream();
368→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
369→    auto src_data = src.data_ptr<scalar_t>();
370→    auto out_data = out.data_ptr<scalar_t>();
371→
372→    if (K == 1)
373→      gather_coo_kernel<scalar_t><<<BLOCKS(1, E), THREADS, 0, stream>>>(
374→          src_data, index_info, out_data, E, N);
375→    else
376→      gather_coo_broadcast_kernel<scalar_t>
377→          <<<BLOCKS(1, E * K), THREADS, 0, stream>>>(src_data, index_info,
378→                                                     out_data, E, K, N);
379→  });
380→
381→  return out;
382→}
