  8→enum ReductionType { SUM, MEAN, MUL, DIV, MIN, MAX };
  9→
 10→const std::map<std::string, ReductionType> reduce2REDUCE = {
 11→    {"sum", SUM}, {"mean", MEAN}, {"mul", MUL},
 12→    {"div", DIV}, {"min", MIN},   {"max", MAX},
 13→};
 14→
 15→#define AT_DISPATCH_REDUCTION_TYPES(reduce, ...)                               \
 16→  [&] {                                                                        \
 17→    switch (reduce2REDUCE.at(reduce)) {                                        \
 18→    case SUM: {                                                                \
 19→      static constexpr ReductionType REDUCE = SUM;                                        \
 20→      return __VA_ARGS__();                                                    \
 21→    }                                                                          \
 22→    case MEAN: {                                                               \
 23→      static constexpr ReductionType REDUCE = MEAN;                                       \
 24→      return __VA_ARGS__();                                                    \
 25→    }                                                                          \
 26→    case MUL: {                                                                \
 27→      static constexpr ReductionType REDUCE = MUL;                                        \
 28→      return __VA_ARGS__();                                                    \
 29→    }                                                                          \
 30→    case DIV: {                                                                \
 31→      static constexpr ReductionType REDUCE = DIV;                                        \
 32→      return __VA_ARGS__();                                                    \
 33→    }                                                                          \
 34→    case MIN: {                                                                \
 35→      static constexpr ReductionType REDUCE = MIN;                                        \
 36→      return __VA_ARGS__();                                                    \
 37→    }                                                                          \
 38→    case MAX: {                                                                \
 39→      static constexpr ReductionType REDUCE = MAX;                                        \
 40→      return __VA_ARGS__();                                                    \
 41→    }                                                                          \
 42→    }                                                                          \
 43→  }()
