 45→template <typename scalar_t, ReductionType REDUCE> struct Reducer {
 46→  static inline __host__ __device__ scalar_t init() {
 47→    if (REDUCE == MUL || REDUCE == DIV)
 48→      return (scalar_t)1;
 49→    else if (REDUCE == MIN)
 50→      return std::numeric_limits<scalar_t>::max();
 51→    else if (REDUCE == MAX)
 52→      return std::numeric_limits<scalar_t>::lowest();
 53→    else
 54→      return (scalar_t)0;
 55→  }
 56→
 57→  static inline __host__ __device__ void update(scalar_t *val,
 58→                                                scalar_t new_val) {
 59→    if (REDUCE == SUM || REDUCE == MEAN)
 60→      *val = *val + new_val;
 61→    else if (REDUCE == MUL)
 62→      *val = *val * new_val;
 63→    else if (REDUCE == DIV)
 64→      *val = *val / new_val;
 65→    else if ((REDUCE == MIN && new_val < *val) ||
 66→             (REDUCE == MAX && new_val > *val)) {
 67→      *val = new_val;
 68→    }
 69→  }
 70→
 71→  static inline __host__ __device__ void update(scalar_t *val, scalar_t new_val,
 72→                                                int64_t *arg, int64_t new_arg) {
 73→    if (REDUCE == SUM || REDUCE == MEAN)
 74→      *val = *val + new_val;
 75→    else if (REDUCE == MUL)
 76→      *val = *val * new_val;
 77→    else if (REDUCE == DIV)
 78→      *val = *val / new_val;
 79→    else if ((REDUCE == MIN && new_val < *val) ||
 80→             (REDUCE == MAX && new_val > *val)) {
 81→      *val = new_val;
 82→      *arg = new_arg;
 83→    }
 84→  }
 85→
 86→  static inline __host__ __device__ void write(scalar_t *address, scalar_t val,
 87→                                               int64_t *arg_address,
 88→                                               int64_t arg, int count) {
 89→    if (REDUCE == SUM || REDUCE == MUL || REDUCE == DIV)
 90→      *address = val;
 91→    else if (REDUCE == MEAN)
 92→      *address = val / (scalar_t)(count > 0 ? count : 1);
 93→    else if (REDUCE == MIN || REDUCE == MAX) {
 94→      if (count > 0) {
 95→        *address = val;
 96→        *arg_address = arg;
 97→      } else
 98→        *address = (scalar_t)0;
 99→    }
100→  }
101→
102→  static inline __device__ void atomic_write(scalar_t *address, scalar_t val) {
103→    if (REDUCE == SUM || REDUCE == MEAN)
104→      atomAdd(address, val);
105→    else if (REDUCE == MUL)
106→      atomMul(address, val);
107→    else if (REDUCE == DIV)
108→      atomDiv(address, val);
109→    else if (REDUCE == MIN)
110→      atomMin(address, val);
111→    else if (REDUCE == MAX)
112→      atomMax(address, val);
113→  }
114→};
