 62→template <typename scalar_t, ReductionType REDUCE>
 63→__global__ void segment_csr_broadcast_kernel(
 64→    const scalar_t *src_data,
 65→    const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
 66→    scalar_t *out_data, int64_t *arg_out_data, size_t N, size_t K, size_t E) {
 67→
 68→  // Each thread processes exactly one row. It turned out that is more
 69→  // efficient than using shared memory due to avoiding synchronization
 70→  // barriers.
 71→
 72→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 73→  int row_idx = thread_idx / K;
 74→  int lane_idx = thread_idx % K;
 75→
 76→  if (thread_idx < N * K) {
 77→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
 78→    int64_t row_start = __ldg(indptr_info.data + offset);
 79→    int64_t row_end = __ldg(indptr_info.data + offset +
 80→                            indptr_info.strides[indptr_info.dims - 1]);
 81→
 82→    scalar_t val = Reducer<scalar_t, REDUCE>::init();
 83→    int64_t arg;
 84→
 85→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E * K;
 86→    for (int64_t src_idx = row_start; src_idx < row_end; src_idx++) {
 87→      Reducer<scalar_t, REDUCE>::update(
 88→          &val, src_data[offset + K * src_idx + lane_idx], &arg, src_idx);
 89→    }
 90→
 91→    Reducer<scalar_t, REDUCE>::write(out_data + thread_idx, val,
 92→                                     arg_out_data + thread_idx, arg,
 93→                                     row_end - row_start);
 94→  }
 95→}
