170→template <typename scalar_t, int TB>
171→__global__ void
172→gather_csr_kernel(const scalar_t *src_data,
173→                  const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
174→                  scalar_t *out_data, size_t N, size_t E) {
175→
176→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
177→  int row_idx = thread_idx / TB;
178→  int lane_idx = thread_idx % TB;
179→
180→  if (row_idx < N) {
181→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
182→    int row_start = __ldg(indptr_info.data + offset);
183→    int row_end = __ldg(indptr_info.data + offset +
184→                        indptr_info.strides[indptr_info.dims - 1]);
185→    scalar_t val = __ldg(src_data + row_idx);
186→
187→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E;
188→    for (int out_idx = row_start + lane_idx; out_idx < row_end; out_idx += TB) {
189→      out_data[offset + out_idx] = val; // "Mostly" coalesced.
190→    }
191→  }
192→}
