194→template <typename scalar_t>
195→__global__ void gather_csr_broadcast_kernel(
196→    const scalar_t *src_data,
197→    const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
198→    scalar_t *out_data, size_t N, size_t K, size_t E) {
199→
200→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
201→  int row_idx = thread_idx / K;
202→  int lane_idx = thread_idx % K;
203→
204→  if (thread_idx < N * K) {
205→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
206→    int row_start = __ldg(indptr_info.data + offset);
207→    int row_end = __ldg(indptr_info.data + offset +
208→                        indptr_info.strides[indptr_info.dims - 1]);
209→
210→    scalar_t val = src_data[thread_idx]; // Coalesced.
211→
212→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E * K;
213→    for (int out_idx = row_start; out_idx < row_end; out_idx++) {
214→      out_data[offset + K * out_idx + lane_idx] = val; // "Mostly" coalesced.
215→    }
216→  }
217→}
