261→  auto N = src.size(dim) * (indptr.numel() / indptr.size(-1));
262→  auto K = src.numel() / N;
263→  auto E = out.size(dim);
264→
265→  auto indptr_info = at::cuda::detail::getTensorInfo<int64_t, int>(indptr);
266→  auto stream = at::cuda::getCurrentCUDAStream();
267→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
268→    auto src_data = src.data_ptr<scalar_t>();
