 3→#include <ATen/cuda/detail/TensorInfo.cuh>
 4→
 5→// We need our own `IndexToOffset` implementation since we do not want to
 6→// access the last element of the `indexptr`.
 7→template <typename scalar_t> struct IndexPtrToOffset {
 8→  static inline __host__ __device__ int
 9→  get(int idx, const at::cuda::detail::TensorInfo<scalar_t, int> &info) {
10→    int offset = idx % (info.sizes[info.dims - 1] - 1);
11→    offset *= info.strides[info.dims - 1];
12→    idx /= info.sizes[info.dims - 1] - 1;
13→    for (int i = info.dims - 2; i >= 0; --i) {
14→      offset += (idx % info.sizes[i]) * info.strides[i];
15→      idx /= info.sizes[i];
16→    }
17→    return offset;
18→  }
19→};
